#include <stdio.h>

int main(void)
{
    int year;
    int days[12] = {31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31};

    printf("Please enter the year:");
    if (scanf("%d", &year) != 1) {
        return 1;
    }

    if ((year % 4 == 0 && year % 100 != 0) || year % 400 == 0) {
        days[1] = 29;
    }

    for (int block = 0; block < 2; block++) {
        for (int month = 0; month < 6; month++) {
            if (month > 0) {
                printf(",");
            }
            printf("%d", days[block * 6 + month]);
        }
        printf("\n");
    }
    return 0;
}
